sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    debugger;
    console.debug(">>>>Add Department Button:\nEvent=", event, event.name);

    const detail = event.context.item.parent;
    // 追記department行の列数をカウント
    const index = event.context.item.index;
    // すでに5行追加されている場合にはキャンセル
    if (index > 5) return;

    if (index + 1 >= detail.value.departmentArray.length) {
        detail.value.departmentArray.push({
            dept: {
                value: "",
                displayValue: ""
            },
            position: {
                value: "",
                displayValue: ""
            },
            tanto: {
                value: "",
                displayValue: ""
            },
            visible: false
        });

    }
    detail.value.departmentArray[index + 1].visible = true;

    // api.setState("records", api.state.records.map(v => v));

    api.setState("records", (prev) => prev.currentValue.map((rec,index) => {
        return rec;
    }));
}
